insert into public.people (nome, tipo)
  select distinct cliente, 'cliente' from _imp i
  where not exists (select 1 from public.people p where p.nome = i.cliente);

do $$
declare g record; v_sale bigint; v_total numeric;
begin
  for g in select distinct grp, data, cliente from _imp order by grp loop
    insert into public.sales (pessoa_id, operador_id, data_hora, total, forma_pagamento, status, observacoes)
    select p.id, 'c020deda-1678-4007-a522-842edef1d4ca'::uuid,
           ((g.data::text || ' 12:00:00-03:00')::timestamptz), 0, 'pix', 'ativa', 'Import planilha MAIO'
    from public.people p where p.nome = g.cliente order by p.id limit 1
    returning id into v_sale;

    insert into public.sale_items (sale_id, material_id, peso, preco_unitario, subtotal)
    select v_sale, m.id, i.peso, i.preco, i.subtotal
    from _imp i join public.materials m on m.nome = i.material
    where i.grp = g.grp;

    select coalesce(sum(subtotal),0) into v_total from public.sale_items where sale_id = v_sale;
    update public.sales set total = v_total where id = v_sale;
  end loop;
end $$;
